    return () => { alive = false; };
  }, [page, category, type, brand, maxFollowers, minPayout, sort, nonce]);

  const activeCount = [type, maxFollowers, minPayout].filter(Boolean).length;
  const clearAll = () => { setQ(''); setParams({}, { replace: true }); };

  return (
