    ? campaign.eligibility.locations.join(", ")
    : "India";

  const reward = payoutLabel(campaign);

  // Reset the image when the card's campaign changes.
  useEffect(() => {
    setActiveImage(0);
    setImageError(false);
  }, [campaign?.id]);

