export default function CampaignSidebar({
  filters,
  onChange,
  onClear,
}) {
  const selectedPlatforms = filters.platforms || [];

  const togglePlatform = (platform) => {
    const updated = selectedPlatforms.includes(platform)
      ? selectedPlatforms.filter(item => item !== platform)
      : [...selectedPlatforms, platform];

    onChange("platforms", updated);
  };

  return (


      {/* Header */}







            Filters





          Clear all



      {/* Category */}

         onChange("category", "")}
        />

        {categories.map(category => (

              onChange(
                "category",
                filters.category === category ? "" : category
              )
            }
          />
        ))}


      {/* Campaign type */}

        {campaignTypes.map(type => (
           onChange("type", type.value)}
          />
        ))}


      {/* Platform */}

        {platforms.map(platform => (
           togglePlatform(platform)}
          />
        ))}


      {/* Followers */}

        {followerOptions.map(option => (
           onChange("maxFollowers", option.value)}
          />
        ))}


      {/* Minimum payout */}





            â‚¹0

              â‚¹{Number(filters.minPayout || 0).toLocaleString("en-IN")}



           onChange("minPayout", e.target.value)}
            className="w-full cursor-pointer accent-[#38251c]"
          />



            â‚¹0
            â‚¹50,000+




  );
}

