  align-items: center;
  gap: 7px;
  padding: 7px 11px;
  border: 1px solid rgba(255,255,255,.22);
  border-radius: 30px;
  background: rgba(255,255,255,.14);
  color: #fff;
  backdrop-filter: blur(10px);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .09em;
}

.spotlight-tag-light {
  background: rgba(242,193,162,.95);
  border-color: transparent;
