}

.spotlight-primary,
.spotlight-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 43px;
  padding: 0 17px;
  border-radius: 10px;
  font-size: 12px;
  font-weight: 800;
  transition: all .2s ease;
}

.spotlight-primary {
  background: #f0c3a5;
  color: #302019;
}

.spotlight-primary:hover {
  background: #ffdcc3;
  transform: translateY(-2px);
}

.spotlight-secondary {
  color: white;
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.35);
  backdrop-filter: blur(8px);
}

.spotlight-secondary:hover {
  background: rgba(255,255,255,.23);
}

.spotlight-arrow {
  position: absolute;
  z-index: 3;
  top: 50%;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.3);
  background: rgba(255,255,255,.17);
  color: white;
  backdrop-filter: blur(8px);
  transform: translateY(-50%);
