  .campaign-spotlight-content .mt-6 {
    margin-top: 17px;
  }

  .spotlight-arrow {
    width: 30px;
    height: 30px;
    top: 47px;
  }

  .spotlight-arrow-left { left: auto; right: 53px; }
  .spotlight-arrow-right { right: 16px; }

  .spotlight-dots {
    bottom: 12px;
    right: 17px;
  }

  .spotlight-primary,
  .spotlight-secondary {
    min-height: 39px;
    padding: 0 12px;
    font-size: 10px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .campaign-spotlight-image {
    animation: none;
  }
}
@keyframes campaignFade {
  from {
    opacity: 0.65;
  }
  to {
    opacity: 1;
  }
}
