  Activity, Users, Clock3, MousePointerClick, RefreshCw, AlertCircle, Search,
  ChevronLeft, ChevronRight, BadgeCheck, CheckCircle2, Eye, X, Mail, Phone,
  Building2, ExternalLink
} from 'lucide-react';
