import React, { useEffect, useState } from 'react';
import { 
  Mail, Search, RefreshCw, ChevronLeft, ChevronRight, 
  CheckCircle2, Plus, Download, Copy, Check, AlertCircle 
} from 'lucide-react';
import { fetchNewsletterSubscribers, subscribeNewsletterAdmin } from '../services/api';

export default function NewsletterPage() {
  const [data, setData] = useState({ content: [], totalElements: 0, totalPages: 1 });
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [activeOnly, setActiveOnly] = useState('');
  const [page, setPage] = useState(0);
  const [copiedEmail, setCopiedEmail] = useState(null);

  // Add subscriber modal state
  const [showAddModal, setShowAddModal] = useState(false);
  const [newEmail, setNewEmail] = useState('');
  const [addLoading, setAddLoading] = useState(false);
  const [addMsg, setAddMsg] = useState(null);

  const loadData = () => {
    setLoading(true);
    fetchNewsletterSubscribers({ activeOnly, search, page, size: 15 })
      .then((res) => setData(res))
      .catch((err) => console.error('Subscribers load error:', err))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    loadData();
  }, [activeOnly, page]);

  useEffect(() => {
    const timer = setTimeout(() => {
      setPage(0);
      loadData();
    }, 350);
    return () => clearTimeout(timer);
  }, [search]);

  const handleAddSubscriber = async (e) => {
    e.preventDefault();
    if (!newEmail.trim()) return;
    setAddLoading(true);
    setAddMsg(null);

    try {
      await subscribeNewsletterAdmin(newEmail.trim());
      setAddMsg({ type: 'success', text: 'Email added successfully.' });
      setNewEmail('');
      loadData();
      setTimeout(() => setShowAddModal(false), 1200);
    } catch (err) {
      setAddMsg({ type: 'error', text: err.message || 'Failed to add subscriber.' });
    } finally {
      setAddLoading(false);
    }
  };

  const copyToClipboard = (email) => {
    navigator.clipboard.writeText(email);
    setCopiedEmail(email);
    setTimeout(() => setCopiedEmail(null), 2000);
  };

  const exportCsv = () => {
    const rows = [
      ['Email', 'Active', 'Subscribed At'],
      ...data.content.map((s) => [s.email, s.isActive ? 'true' : 'false', s.subscribedAt || '']),
    ];
    const csvContent = 'data:text/csv;charset=utf-8,' + rows.map((e) => e.join(',')).join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', 'newsletter_subscribers.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const items = data?.content || [];

  return (


      {/* Top Header */}





Newsletter Subscribers


            Registered creators and brand leads subscribed to campaign newsletters and platform alerts.







            Export CSV


           { setShowAddModal(true); setAddMsg(null); }}
            className="flex items-center gap-1.5 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-bold shadow-sm transition"
          >

            Add Subscriber




      {/* KPI Stats */}





Total Subscribed

{data.totalElements.toLocaleString()}




Active Status

100%




Digest Delivery

Bi-weekly brief digests



      {/* Filter Bar */}





           setSearch(e.target.value)}
            placeholder="Search subscribers by email..."
            className="w-full pl-8 pr-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-semibold text-slate-700 outline-none focus:bg-white focus:border-blue-500 transition"
          />







      {/* Table */}








                Email Address
                Status
                Subscribed Date
                Actions



              {loading ? (
                Array.from({ length: 5 }).map((_, i) => (







                ))
              ) : items.length > 0 ? (
                items.map((sub) => (



                      {sub.email}




                         Active




                      {sub.subscribedAt ? new Date(sub.subscribedAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }) : 'â€”'}



                       copyToClipboard(sub.email)}
                        className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 text-[11px] font-semibold transition"
                      >
                        {copiedEmail === sub.email ? (
                          <> Copied</>
                        ) : (
                          <> Copy</>
                        )}



                ))
              ) : (



                    No subscribers found.


              )}




        {/* Pagination Bar */}


          {data.totalElements} total subscribers


             setPage((p) => Math.max(0, p - 1))}
              className="p-1.5 rounded-lg border border-slate-200 hover:bg-slate-50 disabled:opacity-40 transition"
            >


            Page {page + 1} of {Math.max(1, data.totalPages)}
            = data.totalPages - 1}
              onClick={() => setPage((p) => p + 1)}
              className="p-1.5 rounded-lg border border-slate-200 hover:bg-slate-50 disabled:opacity-40 transition"
            >






      {/* Add Subscriber Modal */}
      {showAddModal && (





Add Subscriber Manually

Enter a creator or brand email to enroll them in platform updates.


               setNewEmail(e.target.value)}
                placeholder="subscriber@domain.com"
                className="w-full px-3.5 py-2 text-xs border border-slate-200 rounded-xl outline-none focus:border-blue-500 font-semibold"
              />

              {addMsg && (


                  {addMsg.text}

              )}



                 setShowAddModal(false)}
                  className="px-3.5 py-1.5 rounded-xl border border-slate-200 text-xs font-semibold text-slate-600 hover:bg-slate-50"
                >
                  Cancel


                  {addLoading ? 'Adding...' : 'Subscribe'}





      )}

  );
}

