);

const CampaignCard = ({ campaign }) => {
  const [failed, setFailed] = useState(() => new Set());
  const [activeSrc, setActiveSrc] = useState(null);
  const [prevSrc, setPrevSrc] = useState(null);
  const [seen, setSeen] = useState(() => new Set());

  const images = useMemo(
    () =>
      uniqueStrings(campaign?.images || []).filter((src) => !failed.has(src)),
    [campaign?.images, failed]
  );

  const current = images.includes(activeSrc) ? activeSrc : images[0];
  const currentRef = useRef(current);
  currentRef.current = current;

  const brand = campaign?.brandName || "Brand";
  const type = getType(campaign);
  const brandStyle = getBrandStyle
    ? getBrandStyle(brand)
    : { bg: "#eff6ff", color: "#1d4ed8" };
  const status = getStatus ? getStatus(campaign) : { closed: false };

  const reward = getReward(campaign);

  const brandLogo =
    campaign?.brandLogo ||
    campaign?.brand_logo ||
    campaign?.logoUrl ||
    campaign?.logo ||
    campaign?.brand?.logo;

  const applyLink = useMemo(() => {
    try {
      if (typeof getApplyUrl === "function") {
        const url = getApplyUrl(campaign);
        if (url && url !== "#" && url !== "undefined") return url;
      }
    } catch (_) {}
    return (
      campaign?.applyProxyUrl ||
      campaign?.applyUrl ||
      campaign?.apply_url ||
      campaign?.formUrl ||
      `/campaigns/${campaign?.id}`
    );
  }, [campaign]);

  const isExternal =
    applyLink.startsWith("http://") || applyLink.startsWith("https://");

  // Reset slideshow on campaign change
  useEffect(() => {
    setActiveSrc(null);
    setPrevSrc(null);
    setSeen(new Set());
    setFailed(new Set());
  }, [campaign?.id]);

  // Preload next image
  useEffect(() => {
    if (images.length < 2 || !current) return;
    preload(images[(images.indexOf(current) + 1) % images.length]);
  }, [current, images]);

  // Rotate images (crossfade)
  useEffect(() => {
    if (images.length < 2) return undefined;

    let cancelled = false;
    let swapTimer;

    const timer = setInterval(async () => {
      if (document.hidden) return;

      const shown = currentRef.current;
      const next = images[(images.indexOf(shown) + 1) % images.length];
      if (!next || next === shown) return;

      const ok = await preload(next);
      if (cancelled) return;

      if (!ok) {
        setFailed((prev) => new Set(prev).add(next));
        return;
      }

      setSeen((prev) => new Set(prev).add(next));
      swapTimer = setTimeout(() => {
        if (cancelled) return;
        setPrevSrc(shown);
        setActiveSrc(next);
      }, 40);
    }, ROTATE_MS);

    return () => {
      cancelled = true;
      clearInterval(timer);
      clearTimeout(swapTimer);
    };
  }, [campaign?.id, images]);

  if (!campaign) return null;

  const activeIndex = Math.max(0, images.indexOf(current));
  const layers = images.filter(
    (src) => src === current || src === prevSrc || seen.has(src)
  );

  const applyClass =
    "flex h-8 flex-1 items-center justify-center gap-1 rounded-lg bg-blue-600 text-[11px] font-medium text-white transition-colors hover:bg-blue-700 sm:h-10 sm:text-[13px]";

  const applyLabel = (
    <>
      Apply
      Apply now

    </>
  );

  return (

      {/* Image (inset, so the card has breathing room) */}


        {images.length > 0 ? (
          layers.map((src) => {
            const isActive = src === current;
            const isPrev = src === prevSrc;

            return (
               setFailed((prev) => new Set(prev).add(src))}
                className={`absolute inset-0 h-full w-full object-cover object-center transition-[opacity,transform] duration-700 group-hover:scale-[1.04] ${
                  isActive
                    ? "z-10 opacity-100"
                    : isPrev
                    ? "z-[5] opacity-100"
                    : "z-0 opacity-0"
                }`}
              />
            );
          })
        ) : (



              {brand.charAt(0).toUpperCase()}


        )}




        {/* Type tag */}

          {type}


        {/* Image indicators (hidden on phones to keep it clean) */}
        {images.length > 1 && (


            {images.map((src, index) => (

            ))}

        )}


      {/* Body */}


        {/* Brand */}



            {brandLogo ? (

            ) : (
              brand.charAt(0).toUpperCase()
            )}


            {brand}



        {/* Title (stretched link makes the whole card clickable) */}



            {campaign.campaignTitle || "Creator campaign"}



        {/* Phone: only the reward */}


          {reward}


        {/* Tablet / desktop: three clean rows */}










        {/* Actions */}



            View brief


          {status?.closed ? (

              Closed

          ) : isExternal ? (

              {applyLabel}

          ) : (

              {applyLabel}

          )}



  );
};

