function Gallery({ images, brand }) {
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);
  const [failed, setFailed] = useState(() => new Set());
  const touchX = useRef(null);

  const visible = useMemo(() => images.filter((s) => !failed.has(s)), [images, failed]);
  const count = visible.length;
  const current = count ? index % count : 0;

  const go = useCallback(
    (step) => {
      if (count > 1) setIndex((current + step + count) % count);
    },
    [count, current]
  );

  useEffect(() => {
    if (count < 2 || paused) return undefined;
    const timer = setInterval(() => {
      if (!document.hidden) setIndex((i) => (i + 1) % count);
    }, ROTATE_MS);
    return () => clearInterval(timer);
  }, [count, paused, current]);

  const frame = "relative aspect-[4/3] w-full overflow-hidden rounded-xl bg-slate-100 lg:aspect-auto lg:h-full";

  if (count === 0) {
    const { bg, color } = brandStyle(brand);
    return (



          {brand.charAt(0).toUpperCase()}


    );
  }

  const arrow =
    "absolute top-1/2 z-20 grid h-9 w-9 -translate-y-1/2 place-items-center rounded-full bg-white/95 text-slate-700 shadow-md transition hover:bg-white";

  return (

 setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocus={() => setPaused(true)}
      onBlur={() => setPaused(false)}
      onKeyDown={(e) => {
        if (e.key === "ArrowLeft") go(-1);
        if (e.key === "ArrowRight") go(1);
      }}
      onTouchStart={(e) => {
        touchX.current = e.touches[0].clientX;
      }}
      onTouchEnd={(e) => {
        if (touchX.current === null) return;
        const delta = e.changedTouches[0].clientX - touchX.current;
        touchX.current = null;
        if (Math.abs(delta) > 40) go(delta < 0 ? 1 : -1);
      }}
      className={`relative rounded-xl lg:h-full ${FOCUS}`}
    >


        {visible.map((src, i) => (
           setFailed((prev) => new Set(prev).add(src))}
          />
        ))}


      {count > 1 && (
        <>
           go(-1)} aria-label="Previous image" className={`${arrow} left-3 ${FOCUS}`}>


           go(1)} aria-label="Next image" className={`${arrow} right-3 ${FOCUS}`}>





            {visible.map((src, i) => (
               setIndex(i)}
                aria-label={`Show image ${i + 1}`}
                aria-current={i === current}
                className={`h-9 w-9 shrink-0 overflow-hidden rounded-lg transition ${FOCUS} ${
                  i === current ? "opacity-100 ring-2 ring-white" : "opacity-60 hover:opacity-100"
                }`}
              >


            ))}

        </>
      )}

  );
}

