const PAGE_SIZE = 12;

export default function Campaigns() {
  const [params, setParams] = useSearchParams();

  const get = (key, fallback = "") => params.get(key) || fallback;

  const page = Math.max(0, Number(get("page", 0)) || 0);
  const category = get("category");
  const type = get("type");
  const brand = get("brand");
  const maxFollowers = get("maxFollowers");
  const minPayout = get("minPayout");
  const sort = get("sort", "createdAt:desc");

  const [query, setQuery] = useState(brand);
  const [mobileFiltersOpen, setMobileFiltersOpen] = useState(false);
  const [retry, setRetry] = useState(0);

  const [state, setState] = useState({
    loading: true,
    error: null,
    items: [],
    pages: 1,
    total: 0,
  });

  // Update URL parameters.
  const update = (patch, keepPage = false) => {
    const next = new URLSearchParams(params);

    Object.entries(patch).forEach(([key, value]) => {
      if (value === "" || value === null || value === undefined) {
        next.delete(key);
      } else {
        next.set(key, String(value));
      }
    });

    if (!keepPage) next.delete("page");

    setParams(next, { replace: true });
  };

  // Sync search input with URL.
  useEffect(() => {
    setQuery(brand);
  }, [brand]);

  // Debounced search.
  useEffect(() => {
    const timer = setTimeout(() => {
      const clean = query.trim();

      if (clean !== brand) {
        update({ brand: clean });
      }
    }, 400);

    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [query]);

  // Fetch campaigns using the existing API.
  useEffect(() => {
    let active = true;

    setState(previous => ({
      ...previous,
      loading: true,
      error: null,
    }));

    const [sortBy, sortDirection] = sort.split(":");

    fetchCampaigns({
      page,
      size: PAGE_SIZE,
      brand,
      category,
      campaignType: type,
      maxFollowers,
      minPayout,
      sortBy,
      sortDirection,
    })
      .then(data => {
        if (!active) return;

        setState({
          loading: false,
          error: null,
          items: data?.content || [],
          pages: Math.max(1, data?.totalPages || 1),
          total: data?.totalElements || 0,
        });
      })
      .catch(error => {
        if (!active) return;

        setState(previous => ({
          ...previous,
          loading: false,
          error: error?.message || "Unable to load campaigns.",
        }));
      });

    return () => {
      active = false;
    };
  }, [
    page,
    category,
    type,
    brand,
    maxFollowers,
    minPayout,
    sort,
    retry,
  ]);

  const activeCount = [
    category,
    type,
    maxFollowers,
    minPayout,
  ].filter(Boolean).length;

  const clearAll = () => {
    setQuery("");
    setParams({}, { replace: true });
    setMobileFiltersOpen(false);
  };

  const activeCategory =
    CATEGORIES.find(item => item.value === category)?.label ||
    "All campaigns";

  const sidebar = (



      {/* Category */}



          {CATEGORIES.map(({ label, value, icon: Icon }) => (

               update({ category: value })}
                className="h-4 w-4 accent-blue-600"
              />

              {label}

          ))}



      {/* Collaboration type */}



          {[
            { label: "All types", value: "" },
            { label: "Paid campaigns", value: "PAID" },
            { label: "Product barter", value: "BARTER" },
          ].map(option => (

               update({ type: option.value })}
                className="h-4 w-4 accent-blue-600"
              />
              {option.label}

          ))}



      {/* Followers */}

         update({ maxFollowers: event.target.value })}
          className="h-10 w-full rounded-xl border border-slate-200 bg-slate-50/70 px-3 text-xs sm:text-sm text-slate-700 outline-none focus:border-blue-600 focus:bg-white transition"
        >
          Any audience size
          Up to 5,000
          Up to 10,000
          Up to 25,000
          Up to 50,000



      {/* Minimum payout */}

         update({ minPayout: event.target.value })}
          className="h-10 w-full rounded-xl border border-slate-200 bg-slate-50/70 px-3 text-xs sm:text-sm text-slate-700 outline-none focus:border-blue-600 focus:bg-white transition"
        >
          Any reward
          â‚¹1,000+
          â‚¹3,000+
          â‚¹5,000+
          â‚¹8,000+





        Clear all filters


  );

  return (





        {/* Existing spotlight component */}


        {/* Marketplace layout */}



          {/* Desktop sidebar */}











                    Filters



                {activeCount > 0 && (

                    {activeCount} active

                )}


              {sidebar}



