            {/* Search and sorting */}







                 setQuery(event.target.value)}
                  onKeyDown={event => {
                    if (event.key === "Enter") {
                      update({ brand: query.trim() });
                    }
                  }}
                  placeholder="Search campaigns, brands or keywords..."
                  aria-label="Search campaigns"
                  className="h-11 w-full rounded-xl border border-slate-200/90 bg-white pl-10 pr-10 text-xs sm:text-sm text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-blue-600 focus:ring-4 focus:ring-blue-600/10 shadow-2xs"
                />

